import { createHash } from 'node:crypto';
import MarkdownIt from 'markdown-it';
import type Token from 'markdown-it/lib/token.mjs';
import deflist from 'markdown-it-deflist';
import footnote from 'markdown-it-footnote';

/**
 * Reproduces kramdown's `auto_ids` slug algorithm, so anchors generated by the
 * content scripts keep pointing at the same headings they did under Sinatra:
 *
 *   1. drop every leading non-letter
 *   2. drop every character outside [A-Za-z0-9 -]
 *   3. turn each space into a dash (repeated spaces yield repeated dashes)
 *   4. downcase, falling back to "section" when nothing is left
 */
export function kramdownSlug(text: string): string {
  const slug = text
    .replace(/^[^a-zA-Z]+/, '')
    .replace(/[^a-zA-Z0-9 -]/g, '')
    .replace(/ /g, '-')
    .toLowerCase();

  return slug || 'section';
}

/** The text kramdown would hash into an id: inline markup stripped, code kept. */
function headingText(inline: Token | undefined): string {
  if (!inline?.children) return inline?.content ?? '';

  return inline.children
    .filter((token) => token.type === 'text' || token.type === 'code_inline')
    .map((token) => token.content)
    .join('');
}

/** markdown-it plugin adding kramdown-compatible ids to every heading. */
function autoHeadingIds(md: MarkdownIt): void {
  md.core.ruler.push('kramdown_auto_ids', (state) => {
    const used = new Map<string, number>();

    state.tokens.forEach((token, index) => {
      if (token.type !== 'heading_open') return;

      const base = kramdownSlug(headingText(state.tokens[index + 1]));
      const seen = used.get(base);
      const id = seen === undefined ? base : `${base}-${seen + 1}`;

      used.set(base, seen === undefined ? 0 : seen + 1);
      token.attrSet('id', id);
    });
  });
}

const md = new MarkdownIt({
  html: true, // kramdown passes raw HTML through
  linkify: false, // kramdown does not auto-link bare URLs
  typographer: true, // kramdown's smart quotes / dashes are on by default
  breaks: false,
})
  .use(deflist)
  .use(footnote)
  .use(autoHeadingIds);

/**
 * Rendering the largest pages (artigos.md is ~1.5 MB) costs hundreds of
 * milliseconds, and the source only changes on deploy, so results are memoised
 * by content digest.
 */
const CACHE_LIMIT = 16;
const cache = new Map<string, string>();

export function renderMarkdown(source: string): string {
  const key = createHash('sha256').update(source).digest('hex');
  const cached = cache.get(key);
  if (cached !== undefined) return cached;

  const html = md.render(source);

  if (cache.size >= CACHE_LIMIT) {
    const oldest = cache.keys().next();
    if (!oldest.done) cache.delete(oldest.value);
  }
  cache.set(key, html);

  return html;
}
